mapper.select:
select count(1)
from adi_knowledge_base
where create_time between #{beginTime} and #{endTime}

mapper.update:
update adi_knowledge_base
set item_count      = (select count(1)
                       from adi_knowledge_base_item
                       where kb_uuid = #{uuid}),
    embedding_count = #{embeddingCount}
where uuid = #{uuid}

update adi_knowledge_base
set route_profile_status = 'BUILDING',
    route_profile_status_change_time = current_timestamp
where uuid = #{kbUuid}
  and route_profile_generation = #{generation}
  and route_profile_status in ('NONE', 'STALE', 'FAILED', 'BUILDING')

update adi_knowledge_base
set route_profile_status = 'FAILED',
    route_profile_status_change_time = current_timestamp
where uuid = #{kbUuid}
  and route_profile_generation = #{generation}
